//*****************************************************************************
// DAIKIN - načtení tokenů ze souboru
//
// Pouze načte a uloží tokeny do global contextu.
// REFRESH ZDE NESPouštíme.
// Po načtení odešleme pouze "tokensLoaded" do Daikin startup sync.
//*****************************************************************************

let tokens = {};

try {
    if (
        msg.payload &&
        typeof msg.payload === "string" &&
        msg.payload.trim()
    ) {
        tokens = JSON.parse(msg.payload);

    } else if (
        msg.payload &&
        typeof msg.payload === "object"
    ) {
        tokens = msg.payload;
    }

} catch (e) {
    node.warn(
        "Daikin: nelze parsovat tokens soubor: " +
        e.message
    );

    node.status({
        fill: "red",
        shape: "ring",
        text: "chyba tokens souboru"
    });

    return null;
}


// Uložení tokenů do global context
global.set("daikinTokens", tokens);


// Stav tokenů pro UI
global.set("daikinTokenState", {
    hasRefresh: !!tokens.refresh_token,
    accessExpires: tokens.access_expires || 0
});


if (tokens.refresh_token) {
    node.status({
        fill: "green",
        shape: "dot",
        text: "refresh token načten"
    });

} else {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "refresh token chybí"
    });
}


// Pouze oznámení startup synchronizaci.
// Ta sama rozhodne, zda už máme i Client ID + Secret.
return {
    topic: "daikinStartup",
    payload: "tokensLoaded"
};

//*****************************************************************************
// DAIKIN TOKEN MANAGER
//
// - používá access token, pokud je ještě platný
// - jinak obnoví token přes refresh_token
// - forceRefresh vynutí obnovu
// - chrání proti SOUČASNÉMU spuštění dvou refresh requestů
//*****************************************************************************

const config = global.get("config") || {};
const d = config.daikinConfig || {};
const tokens = global.get("daikinTokens") || {};

const clientId = String(d.clientId || "").trim();
const clientSecret = String(d.clientSecret || "").trim();
const refreshToken = String(tokens.refresh_token || "").trim();


// -----------------------------------------------------------------------------
// KONTROLA KONFIGURACE
// -----------------------------------------------------------------------------

if (!clientId || !clientSecret) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "čekám na Client ID/Secret"
    });

    global.set("daikinTokenState", {
        hasRefresh: !!refreshToken,
        accessExpires: tokens.access_expires || 0
    });

    return null;
}


if (!refreshToken) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "čekám na refresh token"
    });

    global.set("daikinTokenState", {
        hasRefresh: false
    });

    return null;
}


// -----------------------------------------------------------------------------
// JE ACCESS TOKEN JEŠTĚ PLATNÝ?
// -----------------------------------------------------------------------------

const force = (msg.payload === "forceRefresh");

const valid =
    tokens.access_token &&
    tokens.access_expires &&
    (tokens.access_expires - Date.now() > 5 * 60000);


if (valid && !force) {
    node.status({
        fill: "green",
        shape: "dot",
        text: "access OK"
    });

    // Výstup 2 -> GET devices
    return [
        null,
        { daikin_access: tokens.access_token }
    ];
}


// -----------------------------------------------------------------------------
// OCHRANA PROTI PARALELNÍMU REFRESHI
// -----------------------------------------------------------------------------
//
// Daikin refresh token může rotovat.
// Dva současné requesty se stejným refresh tokenem jsou proto nežádoucí.
//

const now = Date.now();
const refreshStarted = global.get("daikinRefreshInFlight") || 0;

// Pokud refresh běží méně než 60 s, druhý nespouštěj.
if (refreshStarted && (now - refreshStarted < 60000)) {
    node.status({
        fill: "blue",
        shape: "ring",
        text: "refresh již probíhá"
    });

    return null;
}

// Starý lock po 60 s považujeme za neplatný.
global.set("daikinRefreshInFlight", now);


// -----------------------------------------------------------------------------
// REFRESH REQUEST
// -----------------------------------------------------------------------------

node.status({
    fill: "blue",
    shape: "ring",
    text: "obnovuji access token..."
});

msg.method = "POST";
msg.url = "https://idp.onecta.daikineurope.com/v1/oidc/token";

msg.headers = {
    "Content-Type": "application/x-www-form-urlencoded"
};

msg.payload =
    "grant_type=refresh_token" +
    "&client_id=" + encodeURIComponent(clientId) +
    "&client_secret=" + encodeURIComponent(clientSecret) +
    "&refresh_token=" + encodeURIComponent(refreshToken);


// Výstup 1 -> POST token endpoint
return [msg, null];

//*****************************************************************************
// DAIKIN - zpracování odpovědi token endpointu
//*****************************************************************************

const base = global.get("sValid_Patch") || "";
const r = msg.payload;
const tokens = global.get("daikinTokens") || {};


// Refresh request je dokončen - vždy uvolnit lock.
global.set("daikinRefreshInFlight", 0);


// -----------------------------------------------------------------------------
// CHYBA
// -----------------------------------------------------------------------------

if (!r || !r.access_token) {
    const err =
        (r && (r.error_description || r.error))
            ? (r.error_description || r.error)
            : ("HTTP " + (msg.statusCode || "?"));

    node.warn(
        "Daikin token refresh selhal: " +
        err
    );

    node.status({
        fill: "red",
        shape: "dot",
        text: "refresh selhal: " + err
    });

    global.set("daikinTokenState", {
        hasRefresh: !!tokens.refresh_token,
        accessExpires: tokens.access_expires || 0,
        lastError: err
    });

    return [
        null,
        {
            saveResult:
                "❌ Token se nepodařilo vygenerovat: " +
                err
        }
    ];
}


// -----------------------------------------------------------------------------
// ÚSPĚCH
// -----------------------------------------------------------------------------

tokens.access_token = r.access_token;

tokens.access_expires =
    Date.now() +
    (r.expires_in ? r.expires_in * 1000 : 10800000);


// Daikin může refresh token rotovat.
// Pokud přišel nový, MUSÍME uložit nový.
if (r.refresh_token) {
    tokens.refresh_token = r.refresh_token;
}


global.set("daikinTokens", tokens);

global.set("daikinTokenState", {
    hasRefresh: true,
    accessExpires: tokens.access_expires
});


const expTime =
    new Date(tokens.access_expires)
        .toLocaleTimeString("cs-CZ");


node.status({
    fill: "green",
    shape: "dot",
    text: "token OK do " + expTime
});


// -----------------------------------------------------------------------------
// ZÁPIS TOKENŮ DO SOUBORU
// -----------------------------------------------------------------------------

const writeMsg = {
    payload: JSON.stringify(tokens, null, 2),
    filename: base + "daikin_tokens.json",
    daikin_access: tokens.access_token
};


const uiMsg = {
    saveResult:
        "✅ Údaje OK, access token platí do " +
        expTime
};


return [
    writeMsg,
    uiMsg
];

const base = global.get('sValid_Patch') || '';
if (!base) {
    node.warn('Daikin: global sValid_Patch neni nastaven');
}
msg.filename = base + 'daikin_tokens.json';
return msg;

const config = global.get('config') || {};
//const config = global.get('defaultDaikin_Config') || {};

const d = config.daikinConfig || { clientId: '', clientSecret: '', pollMinutes: 8 };

const tk = global.get('daikinTokenState') || {};
let tokenState = 'neznamy';
if (tk.hasRefresh) {
    tokenState = 'refresh ulozen';
    if (tk.accessExpires) {
        const left = Math.round((tk.accessExpires - Date.now()) / 60000);
        tokenState += ' | access ' + (left > 0 ? 'plati ' + left + ' min' : 'vyprsel');
    } else {
        tokenState += ' | access zatim negenerovan';
    }
} else {
    tokenState = 'refresh token chybi - vloz v configu';
}
if (tk.lastError) tokenState = 'CHYBA: ' + tk.lastError;

msg.daikinConfig = {
    clientId: d.clientId || '',
    clientSecret: d.clientSecret || '',
    pollMinutes: d.pollMinutes || 8,
    tokenState: tokenState
};
return msg;

//definice globalních funkci
const fGetConfigProperty = global.get('getConfigProperty');
const fSetConfigProperty = global.get('setConfigProperty');

// Vstup z UI: ulozit config (global + soubor) + pripadne novy refresh token
const base = global.get('sValid_Patch') || '';

if (msg.payload === 'testDaikin') {
    return [ { _trigger: 'forceRefresh' }, null ];
}

if (msg.payload === 'saveDaikinConfig') {
    const config = global.get('config') || {};
    config.daikinConfig = msg.daikinConfig;
    global.set('config', config);

    // zprava pro zapis config souboru (vystup 2)
    const cfgFile = { payload: JSON.stringify(config.daikinConfig, null, 2), filename: base + 'daikin_config.json' };

    if (msg.refreshToken) {
        const tokens = global.get('daikinTokens') || {};
        tokens.refresh_token = msg.refreshToken;
        tokens.access_token = null;
        tokens.access_expires = 0;
        global.set('daikinTokens', tokens);
        global.set('daikinTokenState', { hasRefresh: true, accessExpires: 0 });
        return [ { _trigger: 'forceRefresh', _writeFile: true, _tokens: tokens }, cfgFile ];
    }

    return [ { _trigger: 'forceRefresh' }, cfgFile ];
}

return null;

// vystup 1: zapis tokens souboru (jen kdyz _writeFile)
// vystup 2: spust token manager (forceRefresh)
const base = global.get('sValid_Patch') || '';
let writeMsg = null;
let refreshMsg = null;

if (msg._writeFile && msg._tokens) {
    writeMsg = { payload: JSON.stringify(msg._tokens, null, 2), filename: base + 'daikin_tokens.json' };
}
if (msg._trigger === 'forceRefresh') {
    refreshMsg = { payload: 'forceRefresh' };
}
return [writeMsg, refreshMsg];

const base = global.get('sValid_Patch') || '';
msg.filename = base + 'daikin_config.json';
return msg;

//*****************************************************************************
// DAIKIN - načtení konfigurace ze souboru
//
// Pouze načte daikin_config.json a vloží jej do global.config.daikinConfig.
// REFRESH ZDE NESPouštíme.
// Po načtení odešleme pouze "configLoaded" do Daikin startup sync.
//*****************************************************************************

let daikinCfg = null;


// -----------------------------------------------------------------------------
// PARSOVÁNÍ KONFIGURACE
// -----------------------------------------------------------------------------

try {
    if (
        msg.payload &&
        typeof msg.payload === "string" &&
        msg.payload.trim()
    ) {
        daikinCfg = JSON.parse(msg.payload);

    } else if (
        msg.payload &&
        typeof msg.payload === "object"
    ) {
        daikinCfg = msg.payload;
    }

} catch (e) {
    node.warn(
        "Daikin: nelze parsovat config soubor: " +
        e.message
    );

    node.status({
        fill: "red",
        shape: "ring",
        text: "chyba config souboru"
    });

    return null;
}


// -----------------------------------------------------------------------------
// CONFIG NENAČTEN
// -----------------------------------------------------------------------------

if (!daikinCfg) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "config soubor zatím není"
    });

    return null;
}


// -----------------------------------------------------------------------------
// VALIDACE A ULOŽENÍ DO GLOBAL CONFIG
// -----------------------------------------------------------------------------

const config = global.get("config") || {};

config.daikinConfig = {
    clientId: String(daikinCfg.clientId || "").trim(),
    clientSecret: String(daikinCfg.clientSecret || "").trim(),
    pollMinutes: Number(daikinCfg.pollMinutes) || 8
};

global.set("config", config);


if (
    config.daikinConfig.clientId &&
    config.daikinConfig.clientSecret
) {
    node.status({
        fill: "green",
        shape: "dot",
        text: "config načten"
    });

} else {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "config bez ID/Secret"
    });
}


// Pouze oznámení startup synchronizaci.
// Ta sama rozhodne, zda už máme i refresh token.
return {
    topic: "daikinStartup",
    payload: "configLoaded"
};

//*****************************************************************************
// DAIKIN - načtení konfigurace z global.config
//
// Jediným zdrojem konfigurace je centrální global.config.
//
// Zde pouze:
//  1) načteme global.config.daikinConfig
//  2) doplníme bezpečné výchozí hodnoty
//  3) oznámíme Daikin startup sync, že config je připraven
//*****************************************************************************

const config = global.get("config") || {};

// -----------------------------------------------------------------------------
// DAIKIN CONFIG
// -----------------------------------------------------------------------------

if (!config.daikinConfig) {
    config.daikinConfig = {
        clientId: "",
        clientSecret: "",
        pollMinutes: 8
    };

    global.set("config", config);
}

const d = config.daikinConfig;

// Validace / normalizace
d.clientId = String(d.clientId || "").trim();
d.clientSecret = String(d.clientSecret || "").trim();
d.pollMinutes = Math.max(8, Number(d.pollMinutes) || 8);

global.set("config", config);

// -----------------------------------------------------------------------------
// STAV
// -----------------------------------------------------------------------------

if (d.clientId && d.clientSecret) {
    node.status({
        fill: "green",
        shape: "dot",
        text: "config OK"
    });
} else {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "config bez ID/Secret"
    });
}

// -----------------------------------------------------------------------------
// STARTUP SYNC
// -----------------------------------------------------------------------------

return {
    topic: "daikinStartup",
    payload: "configLoaded"
};

const tokens = global.get('daikinTokens') || {};
const access = msg.daikin_access || tokens.access_token;

if (!access) {
    node.warn('Daikin: chybi access token pro poll');
    return null;
}

msg.method = 'GET';
msg.url = 'https://api.onecta.daikineurope.com/v1/gateway-devices';
msg.headers = { 'Authorization': 'Bearer ' + access };
msg.payload = '';
return msg;

const data = msg.payload;

if (msg.statusCode === 401) {
    node.status({ fill: 'red', shape: 'dot', text: '401 - token vyprsel' });
    const tokens = global.get('daikinTokens') || {};
    tokens.access_expires = 0;
    global.set('daikinTokens', tokens);
    return null;
}
if (!Array.isArray(data)) {
    node.status({ fill: 'red', shape: 'dot', text: 'neocekavana odpoved' });
    return null;
}

const sum = arr => Array.isArray(arr) ? arr.reduce((a, b) => a + (typeof b === 'number' ? b : 0), 0) : 0;
const DAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
const DAY_CZ = { monday: 'Po', tuesday: 'Ut', wednesday: 'St', thursday: 'Ct', friday: 'Pa', saturday: 'So', sunday: 'Ne' };

// seskupi dny se shodnym programem do bloku { days:'Po-Pa', items:[{time,mode,temp}] }
function buildSchedule(scheduleVal) {
    if (!scheduleVal || !scheduleVal.value) return null;
    const sv = scheduleVal.value;

    // najdi kontejner s "schedules" - obvykle modes.any, ale projdi vsechny mody
    let container = null, activeKey = null, enabled = false, modeName = null;
    if (sv.modes && typeof sv.modes === 'object') {
        // preferuj currentMode pokud existuje
        const curMode = sv.currentMode && sv.currentMode.value ? sv.currentMode.value : null;
        const modeKeys = Object.keys(sv.modes);
        const tryOrder = curMode && sv.modes[curMode] ? [curMode].concat(modeKeys.filter(k => k !== curMode)) : modeKeys;
        for (const mk of tryOrder) {
            const m = sv.modes[mk];
            if (m && m.schedules) {
                container = m;
                modeName = mk;
                if (m.currentSchedule && m.currentSchedule.value !== undefined) activeKey = String(m.currentSchedule.value);
                if (m.enabled && m.enabled.value !== undefined) enabled = !!m.enabled.value;
                break;
            }
        }
    }
    if (!container || !container.schedules) return null;

    const schedules = container.schedules;
    const keys = Object.keys(schedules);
    if (keys.length === 0) return null;

    // vyber schedule: aktivni, jinak prvni s neprazdnymi akcemi
    const hasActions = k => {
        const s = schedules[k];
        if (!s || !s.actions) return false;
        return Object.keys(s.actions).some(d => s.actions[d] && Object.keys(s.actions[d]).length > 0);
    };
    let useKey = (activeKey !== null && schedules[activeKey]) ? activeKey : null;
    if (!useKey || !hasActions(useKey)) {
        useKey = keys.find(hasActions) || activeKey || keys[0];
    }

    const sch = schedules[useKey];
    if (!sch || !sch.actions) return { enabled, activeKey: useKey, groups: [] };

    const groups = [];
    DAYS.forEach(d => {
        const acts = sch.actions[d] || {};
        const items = Object.keys(acts).sort().map(t => {
            const a = acts[t];
            return {
                time: t.slice(0, 5),
                mode: a.operationMode,
                temp: (a.roomTemperature !== undefined ? a.roomTemperature : null),
                econo: (a.econoMode === 'on'),
                fan: (a.fanSpeed && a.fanSpeed.currentMode) ? a.fanSpeed.currentMode : null
            };
        });
        const key = JSON.stringify(items);
        if (groups.length && groups[groups.length - 1].key === key) {
            groups[groups.length - 1].days.push(d);
        } else {
            groups.push({ key, days: [d], items });
        }
    });

    groups.forEach(g => {
        if (g.days.length === 1) g.label = DAY_CZ[g.days[0]];
        else if (g.days.length === 7) g.label = 'Po-Ne';
        else g.label = DAY_CZ[g.days[0]] + '-' + DAY_CZ[g.days[g.days.length - 1]];
        delete g.key;
        delete g.days;
    });

    return { enabled, activeKey: useKey, groups };
}

const list = [];
data.forEach(dev => {
    const mps = dev.managementPoints || [];
    const cc = mps.find(m => m.managementPointType === 'climateControl');
    const gw = mps.find(m => m.managementPointType === 'gateway');
    const iu = mps.find(m => m.managementPointType === 'indoorUnit');
    const ou = mps.find(m => m.managementPointType === 'outdoorUnit');
    if (!cc) return;

    const v = (o, def) => (o && o.value !== undefined ? o.value : def);

    const name = v(cc.name, dev.id || '?');
    const onOff = v(cc.onOffMode, null);
    const mode = v(cc.operationMode, null);
    const errCode = v(cc.errorCode, '');
    const inError = v(cc.isInErrorState, false);

    let roomTemp = null, outTemp = null;
    if (cc.sensoryData && cc.sensoryData.value) {
        const sd = cc.sensoryData.value;
        if (sd.roomTemperature) roomTemp = sd.roomTemperature.value;
        if (sd.outdoorTemperature) outTemp = sd.outdoorTemperature.value;
    }

    let setpoint = null, spMin = null, spMax = null, spStep = null;
    if (cc.temperatureControl && cc.temperatureControl.value &&
        cc.temperatureControl.value.operationModes && mode &&
        cc.temperatureControl.value.operationModes[mode]) {
        const sp = cc.temperatureControl.value.operationModes[mode].setpoints;
        if (sp && sp.roomTemperature) {
            setpoint = sp.roomTemperature.value;
            spMin = sp.roomTemperature.minValue;
            spMax = sp.roomTemperature.maxValue;
            spStep = sp.roomTemperature.stepValue;
        }
    }

    let fanSpeed = null, fanH = null, fanV = null;
    if (cc.fanControl && cc.fanControl.value &&
        cc.fanControl.value.operationModes && mode &&
        cc.fanControl.value.operationModes[mode]) {
        const fm = cc.fanControl.value.operationModes[mode];
        if (fm.fanSpeed && fm.fanSpeed.currentMode) fanSpeed = fm.fanSpeed.currentMode.value;
        if (fm.fanDirection) {
            if (fm.fanDirection.horizontal && fm.fanDirection.horizontal.currentMode) fanH = fm.fanDirection.horizontal.currentMode.value;
            if (fm.fanDirection.vertical && fm.fanDirection.vertical.currentMode) fanV = fm.fanDirection.vertical.currentMode.value;
        }
    }

    const powerful = v(cc.powerfulMode, null);
    let holiday = null;
    if (cc.holidayMode && cc.holidayMode.value && cc.holidayMode.value.enabled !== undefined) {
        holiday = cc.holidayMode.value.enabled;
    }

    // dalsi planovana akce
    let nextAction = null;
    if (cc.schedule && cc.schedule.value && cc.schedule.value.nextAction) {
        const na = cc.schedule.value.nextAction;
        if (na.startTime) {
            nextAction = {
                time: na.startTime.slice(0, 5),
                mode: na.operationMode || null,
                day: na.actionPeriod ? (DAY_CZ[na.actionPeriod] || na.actionPeriod) : null
            };
        }
    }

    // plan (seskupeny)
    const schedule = buildSchedule(cc.schedule);

    let energy = null;
    if (cc.consumptionData && cc.consumptionData.value && cc.consumptionData.value.electrical) {
        const el = cc.consumptionData.value.electrical;
        const h = el.heating || {}, c = el.cooling || {};
        energy = {
            unit: el.unit || 'kWh',
            today: +(sum((h.d || []).slice(-12)) + sum((c.d || []).slice(-12))).toFixed(1),
            week: +(sum((h.w || []).slice(-7)) + sum((c.w || []).slice(-7))).toFixed(1),
            month: +(sum((h.m || []).slice(-12)) + sum((c.m || []).slice(-12))).toFixed(1),
            cool_month: +sum((c.m || []).slice(-12)).toFixed(1),
            heat_month: +sum((h.m || []).slice(-12)).toFixed(1)
        };
    }

    const ip = gw && gw.ipAddress ? gw.ipAddress.value : null;
    const info = {
        ip: ip,
        fw: gw ? v(gw.firmwareVersion, null) : null,
        serial: gw ? v(gw.serialNumber, null) : null,
        tz: gw ? v(gw.timeZone, null) : null,
        indoor_sw: iu ? v(iu.softwareVersion, null) : null,
        proto: dev.type || null,
        outdoor_err: ou ? v(ou.errorCode, null) : null
    };

    const cloudUp = dev.isCloudConnectionUp ? dev.isCloudConnectionUp.value : null;

    list.push({
        id: dev.id,
        device_name: name,
        cloud_up: cloudUp,
        on_off: onOff,
        mode: mode,
        room_temp: (roomTemp === null ? '--' : roomTemp),
        outdoor_temp: (outTemp === null ? '--' : outTemp),
        setpoint: (setpoint === null ? '--' : setpoint),
        sp_min: spMin, sp_max: spMax, sp_step: spStep,
        fan_speed: fanSpeed, fan_h: fanH, fan_v: fanV,
        powerful: powerful, holiday: holiday,
        next_action: nextAction,
        schedule: schedule,
        energy: energy,
        info: info,
        error_code: errCode,
        in_error: inError,
        updated: new Date().toLocaleTimeString('cs-CZ')
    });
});

if (list.length === 0) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'zadne klimatizace' });
    return null;
}

node.status({ fill: 'green', shape: 'dot', text: list.length + ' klima | ' + new Date().toLocaleTimeString('cs-CZ') });

// =============================================================================
// LINEA API R2.2 - READ-ONLY CLIMATE SNAPSHOT
// =============================================================================
// Do API se zamerne NEexportuji tokeny, Client ID/Secret, IP, serial,
// schedule ani dalsi konfiguracni/servisni udaje.
//
// operationMode je pozadovany/provozni rezim jednotky (heating/cooling/...).
// Neznamena nutne, ze kompresor v danem okamziku fyzicky bezi.
//
// Firmware change:
// - pri prvnim nacteni po startu se zmena NEhlasi
// - zmena se hlasi pouze pokud byla znama predchozi verze a nova je jina
// =============================================================================

const previousFw = global.get("lineaApiClimateFwVersions") || {};
const nextFw = {};

const apiDevices = list.map(d => {
    const fw = d && d.info ? (d.info.fw || null) : null;
    const key = String(d.id || d.device_name || "");

    let firmwareChanged = false;
    if (fw && key && previousFw[key] && previousFw[key] !== fw) {
        firmwareChanged = true;
    }
    if (fw && key) {
        nextFw[key] = fw;
    }

    const energy = d.energy ? {
        unit: d.energy.unit || "kWh",
        todayKWh: d.energy.today ?? null,
        weekKWh: d.energy.week ?? null,
        monthKWh: d.energy.month ?? null,
        coolingMonthKWh: d.energy.cool_month ?? null,
        heatingMonthKWh: d.energy.heat_month ?? null
    } : null;

    return {
        name: d.device_name || null,
        cloudUp: d.cloud_up === null || d.cloud_up === undefined ? null : !!d.cloud_up,
        on: d.on_off === "on" ? true : (d.on_off === "off" ? false : null),
        operationMode: d.mode || null,
        roomTemperatureC: typeof d.room_temp === "number" ? d.room_temp : null,
        outdoorTemperatureC: typeof d.outdoor_temp === "number" ? d.outdoor_temp : null,
        setpointC: typeof d.setpoint === "number" ? d.setpoint : null,
        energy,
        error: !!d.in_error || !!(d.error_code && d.error_code !== "00-" && d.error_code !== "00"),
        errorCode: d.error_code || null,
        firmwareVersion: fw,
        firmwareChanged
    };
});

global.set("lineaApiClimateFwVersions", nextFw);
global.set("lineaApiClimateState", {
    updatedAt: new Date().toISOString(),
    devices: apiDevices
});

msg.payload = list;
return msg;

//*****************************************************************************
// DAIKIN STARTUP SYNC
//
// Řeší race condition při startu Node-RED.
// Config a tokens soubor se mohou načíst v libovolném pořadí.
//
// Refresh se spustí POUZE pokud současně existuje:
//   1) Client ID
//   2) Client Secret
//   3) Refresh Token
//
// Současně je zde krátká ochrana proti dvojímu startup refreshi.
//*****************************************************************************

const config = global.get("config") || {};
const d = config.daikinConfig || {};
const tokens = global.get("daikinTokens") || {};

const clientId = String(d.clientId || "").trim();
const clientSecret = String(d.clientSecret || "").trim();
const refreshToken = String(tokens.refresh_token || "").trim();


// Čekáme na config
if (!clientId || !clientSecret) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "čekám na config"
    });

    return null;
}


// Čekáme na token
if (!refreshToken) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "čekám na refresh token"
    });

    return null;
}


// Ochrana proti tomu, aby dva téměř současné startup eventy
// vyvolaly dva refresh requesty se stejným rotačním refresh tokenem.
const now = Date.now();
const lastStart = context.get("lastStartupRefresh") || 0;

if (now - lastStart < 15000) {
    node.status({
        fill: "green",
        shape: "dot",
        text: "startup refresh již spuštěn"
    });

    return null;
}

context.set("lastStartupRefresh", now);


node.status({
    fill: "green",
    shape: "dot",
    text: "config + token OK"
});


return {
    payload: "forceRefresh",
    topic: "daikinStartupReady"
};
